            self.weight.data_ptr(),
            out.data_ptr(),
            N,
            self.in_channels,
            self.out_channels,
            H_in,
            W_in,
            K,
            stride,
            padding,
            out_pad,
            H_out,
            W_out
        ]

        ptx_launch(self.module,
